{"task_id": "T05", "code": "def solve(grid):
    """Count the number of islands in a binary grid.
    An island is a group of adjacent cells with value 1 connected horizontally or vertically.
    """
    if not grid:
        return 0
    n = len(grid)
    m = len(grid[0]) if n > 0 else 0
    if m == 0:
        return 0
    visited = [[False] * m for _ in range(n)]
    def dfs(i, j):
        stack = [(i, j)]
        while stack:
            x, y = stack.pop()
            if visited[x][y]:
                continue
            visited[x][y] = True
            for dx, dy in ((1,0), (-1,0), (0,1), (0,-1)):
                nx, ny = x+dx, y+dy
                if 0 <= nx < n and 0 <= ny < m and not visited[nx][ny] and grid[nx][ny] == 1:
                    stack.append((nx, ny))
    count = 0
    for i in range(n):
        for j in range(m):
            if grid[i][j] == 1 and not visited[i][j]:
                dfs(i, j)
                count += 1
    return count
"}

