def solve(matrix):
    """Return elements of a (possibly ragged) matrix in clockwise spiral order.
    Works for the standard rectangular case and also for matrices that have empty rows
    or rows of differing lengths.
    """
    if not matrix:
        return []
    total = sum(len(row) for row in matrix)
    if total == 0:
        return []
    # Determine the maximum row length to set right boundary
    max_cols = max(len(row) for row in matrix)
    top, bottom = 0, len(matrix) - 1
    left, right = 0, max_cols - 1
    result = []
    while len(result) < total:
        # top row, left -> right
        for c in range(left, right + 1):
            if top < len(matrix) and c < len(matrix[top]):
                result.append(matrix[top][c])
        top += 1
        if len(result) >= total:
            break
        # right column, top -> bottom
        for r in range(top, bottom + 1):
            if r < len(matrix) and right < len(matrix[r]):
                result.append(matrix[r][right])
        right -= 1
        if len(result) >= total:
            break
        # bottom row, right -> left
        if top <= bottom:
            for c in range(right, left - 1, -1):
                if bottom < len(matrix) and c < len(matrix[bottom]):
                    result.append(matrix[bottom][c])
            bottom -= 1
        if len(result) >= total:
            break
        # left column, bottom -> top
        if left <= right:
            for r in range(bottom, top - 1, -1):
                if r < len(matrix) and left < len(matrix[r]):
                    result.append(matrix[r][left])
            left += 1
    return result

