def solve(matrix):
    """Return elements of a possibly ragged matrix in clockwise spiral order.
    Skips positions that are missing in rows of unequal length.
    """
    # Count total elements
    total = sum(len(row) for row in matrix)
    if total == 0:
        return []
    rows = len(matrix)
    max_cols = max((len(row) for row in matrix), default=0)
    top, bottom = 0, rows - 1
    left, right = 0, max_cols - 1
    result = []
    while len(result) < total and top <= bottom and left <= right:
        # top row, left -> right
        for c in range(left, right + 1):
            if c < len(matrix[top]):
                result.append(matrix[top][c])
        top += 1
        if len(result) >= total:
            break
        # right column, top -> bottom
        for r in range(top, bottom + 1):
            if right < len(matrix[r]):
                result.append(matrix[r][right])
        right -= 1
        if len(result) >= total:
            break
        # bottom row, right -> left
        if top <= bottom:
            for c in range(right, left - 1, -1):
                if c < len(matrix[bottom]):
                    result.append(matrix[bottom][c])
            bottom -= 1
        if len(result) >= total:
            break
        # left column, bottom -> top
        if left <= right:
            for r in range(bottom, top - 1, -1):
                if left < len(matrix[r]):
                    result.append(matrix[r][left])
            left += 1
    return result

