def solve(matrix):
    if not matrix:
        return []
    # Determine the maximum number of columns in any row.
    rows = len(matrix)
    cols = max((len(row) for row in matrix), default=0)
    # Pad rows with None to make a rectangular grid for easy indexing.
    padded = [row + [None] * (cols - len(row)) for row in matrix]
    res = []
    top, bottom, left, right = 0, rows - 1, 0, cols - 1
    while top <= bottom and left <= right:
        # Traverse top row.
        for c in range(left, right + 1):
            val = padded[top][c]
            if val is not None:
                res.append(val)
        top += 1
        # Traverse right column.
        for r in range(top, bottom + 1):
            val = padded[r][right]
            if val is not None:
                res.append(val)
        right -= 1
        if top <= bottom:
            # Traverse bottom row.
            for c in range(right, left - 1, -1):
                val = padded[bottom][c]
                if val is not None:
                    res.append(val)
            bottom -= 1
        if left <= right:
            # Traverse left column.
            for r in range(bottom, top - 1, -1):
                val = padded[r][left]
                if val is not None:
                    res.append(val)
            left += 1
    return res

